-- Restore registered address fields from existing imported descriptions; preserve user places.
update public.facilities set address=btrim(split_part(description,' · ',1))
where owner_id is null and author='지자체 공공데이터' and address is null
and description ~ '^(서울|부산|대구|인천|광주|대전|울산|세종|경기|강원|충청|전라|전북|경상|제주)'
and length(btrim(split_part(description,' · ',1))) between 8 and 300;
